import base64
import json
import os
from datetime import date, datetime
from typing import Any, Dict, List, Optional

import boto3


def _load_document_bytes(source: str) -> bytes:
    if source.startswith("http://") or source.startswith("https://"):
        import urllib.request

        with urllib.request.urlopen(source) as resp:
            return resp.read()
    with open(source, "rb") as f:
        return f.read()


def _normalize_date(value: Optional[str]) -> Optional[str]:
    if not value:
        return None
    value = value.strip()
    for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%d/%m/%Y", "%Y/%m/%d", "%d-%m-%Y", "%m-%d-%Y"):
        try:
            return datetime.strptime(value, fmt).date().isoformat()
        except ValueError:
            pass
    return value


def _money_to_number(value: Optional[str]) -> Optional[float]:
    if value is None:
        return None
    cleaned = "".join(ch for ch in value if ch.isdigit() or ch in ".-")
    if not cleaned or cleaned in {".", "-", "-.", ".-"}:
        return None
    try:
        return float(cleaned)
    except ValueError:
        return None


def _extract_vendor(expense_doc: Dict[str, Any]) -> Optional[str]:
    summary = expense_doc.get("SummaryFields", []) or []
    for field in summary:
        if field.get("Type", {}).get("Text") == "VENDOR_NAME":
            val = field.get("ValueDetection", {}).get("Text")
            if val:
                return val
    for field in summary:
        if field.get("Type", {}).get("Text") in {"SUPPLIER_NAME", "PAYEE_NAME"}:
            val = field.get("ValueDetection", {}).get("Text")
            if val:
                return val
    return None


def _extract_date(expense_doc: Dict[str, Any]) -> Optional[str]:
    summary = expense_doc.get("SummaryFields", []) or []
    for field in summary:
        if field.get("Type", {}).get("Text") == "INVOICE_RECEIPT_DATE":
            val = field.get("ValueDetection", {}).get("Text")
            if val:
                return _normalize_date(val)
    for field in summary:
        if field.get("Type", {}).get("Text") in {"DATE", "DOCUMENT_DATE"}:
            val = field.get("ValueDetection", {}).get("Text")
            if val:
                return _normalize_date(val)
    return None


def _extract_total(expense_doc: Dict[str, Any]) -> Optional[float]:
    summary = expense_doc.get("SummaryFields", []) or []
    for field in summary:
        if field.get("Type", {}).get("Text") in {"TOTAL", "AMOUNT_DUE", "INVOICE_TOTAL"}:
            val = field.get("ValueDetection", {}).get("Text")
            amt = _money_to_number(val)
            if amt is not None:
                return amt
    return None


def _extract_line_items(expense_doc: Dict[str, Any]) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []
    for expense in expense_doc.get("LineItemGroups", []) or []:
        for li in expense.get("LineItems", []) or []:
            row: Dict[str, Any] = {}
            for field in li.get("LineItemExpenseFields", []) or []:
                field_type = field.get("Type", {}).get("Text")
                value = field.get("ValueDetection", {}).get("Text")
                if not field_type or value is None:
                    continue
                key = field_type.lower()
                if key in {"quantity", "qty"}:
                    try:
                        row["quantity"] = float("".join(ch for ch in value if ch.isdigit() or ch in ".-"))
                    except ValueError:
                        row["quantity"] = value
                elif key in {"unit_price", "price", "unitprice"}:
                    row["unit_price"] = _money_to_number(value) if _money_to_number(value) is not None else value
                elif key in {"amount", "line_total", "extended_price", "line_amount"}:
                    row["amount"] = _money_to_number(value) if _money_to_number(value) is not None else value
                else:
                    row[key] = value
            if row:
                items.append(row)
    return items


def extract_invoice_fields(document_source: str, region_name: Optional[str] = None) -> Dict[str, Any]:
    """
    Extract vendor, date, total, and line items from an invoice using Amazon Textract AnalyzeExpense.

    Args:
        document_source: Path to a local file or a URL to the invoice document.
        region_name: AWS region for Textract, defaults to AWS_REGION or us-east-1.

    Returns:
        A dict containing vendor, date, total, and line_items.
    """
    region = region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1"
    textract = boto3.client("textract", region_name=region)

    document_bytes = _load_document_bytes(document_source)
    response = textract.analyze_expense(Document={"Bytes": document_bytes})

    expense_documents = response.get("ExpenseDocuments", []) or []
    if not expense_documents:
        return {"vendor": None, "date": None, "total": None, "line_items": []}

    merged = expense_documents[0]
    result = {
        "vendor": _extract_vendor(merged),
        "date": _extract_date(merged),
        "total": _extract_total(merged),
        "line_items": _extract_line_items(merged),
    }
    return result


if __name__ == "__main__":
    import sys

    src = sys.argv[1]
    print(json.dumps(extract_invoice_fields(src), indent=2, ensure_ascii=False))
